}", "new_string": "// searchTranscriptInSubdirs searches for a session transcript across all Claude project
// directories that correspond to subdirectories of the repo root. Claude Code uses cwd
// (not repo root) for its project directory, so sessions started from subdirectories
// are stored under different project directory names.
func searchTranscriptInSubdirs(ctx context.Context, sessionID string, agent agentpkg.Agent) (string, error) {
	repoRoot, err := paths.WorktreeRoot(ctx)
	if err != nil {
		return "", err
	}

	homeDir, err := os.UserHomeDir()
	if err != nil {
		return "", err
	}

	projectsDir := filepath.Join(homeDir, ".claude", "projects")
	entries, err := os.ReadDir(projectsDir)
	if err != nil {
		return "", err
	}

	// The repo root sanitized is the prefix for all matching project dirs.
	// e.g. repo at /Users/nina/cli → prefix "-Users-nina-cli"
	// Session started from /Users/nina/cli/cmd → dir "-Users-nina-cli-cmd"
	repoPrefix := sanitizePathForSearch(repoRoot)

	for _, entry := range entries {
		if !entry.IsDir() {
			continue
		}
		name := entry.Name()
		// Must start with the repo prefix and either be exactly the prefix
		// (already checked by resolveTranscriptPath) or be a subdirectory of it.
		if name == repoPrefix || !hasPathPrefix(name, repoPrefix) {
			continue
		}
		candidate := agent.ResolveSessionFile(filepath.Join(projectsDir, name), sessionID)
		if _, statErr := os.Stat(candidate); statErr == nil {
			return candidate, nil
		}
	}

	return "", fmt.Errorf("transcript not found in any subdirectory project dir")
}

// sanitizePathForSearch converts a path the same way Claude Code does for project directories.
func sanitizePathForSearch(path string) string {
	// Same logic as claudecode.SanitizePathForClaude — replace non-alphanumeric with dash.
	result := make([]byte, len(path))
	for i := range len(path) {
		c := path[i]
		if (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') {
			result[i] = c
		} else {
			result[i] = '-'
		}
	}
	return string(result)
}

// hasPathPrefix checks if name starts with prefix followed by a dash (subdirectory separator).
func hasPathPrefix(name, prefix string) bool {
	return len(name) > len(prefix) && name[:len(prefix)] == prefix && name[len(prefix)] == '-'
}"}

