 58→func (a *openCodeAgent) Bootstrap() error {
 59→	// opencode has first-run DB migration + node_modules resolution that
 60→	// races with parallel test execution (upstream issue #6935).
 61→	// Run a trivial prompt to force full initialization before tests.
 62→	for i := range 3 {
 63→		ctx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
 64→		cmd := exec.CommandContext(ctx, "opencode", "run", "--model", a.model, "say hi")
 65→		cmd.Env = os.Environ()
 66→		out, err := cmd.CombinedOutput()
 67→		cancel()
 68→		if err == nil {
 69→			return nil
 70→		}
 71→		if i < 2 {
 72→			fmt.Fprintf(os.Stderr, "opencode warmup attempt %d failed: %s\n%s\n", i+1, err, out)
 73→			time.Sleep(5 * time.Second)
 74→		}
 75→	}
 76→	// Non-fatal: warmup failure shouldn't block tests entirely.
 77→	fmt.Fprintln(os.Stderr, "opencode warmup failed after 3 attempts, proceeding anyway")
 78→	return nil
 79→}
