 81→func (a *openCodeAgent) RunPrompt(ctx context.Context, dir string, prompt string, opts ...Option) (Output, error) {
 82→	cfg := &runConfig{}
 83→	for _, o := range opts {
 84→		o(cfg)
 85→	}
 86→
 87→	model := a.model
 88→	if cfg.Model != "" {
 89→		model = cfg.Model
 90→	}
 91→
 92→	args := []string{"run"}
 93→	if model != "" {
 94→		args = append(args, "--model", model)
 95→	}
 96→	args = append(args, prompt)
 97→
 98→	timeout := a.timeout
 99→	if envTimeout := os.Getenv("E2E_TIMEOUT"); envTimeout != "" {
100→		if parsed, err := time.ParseDuration(envTimeout); err == nil {
101→			timeout = parsed
102→		}
103→	}
104→
105→	ctx, cancel := context.WithTimeout(ctx, timeout)
106→	defer cancel()
107→
108→	cmd := exec.CommandContext(ctx, "opencode", args...)
109→	cmd.Dir = dir
110→	cmd.Env = append(os.Environ(), "ENTIRE_TEST_TTY=0")
111→
112→	var stdout, stderr strings.Builder
113→	cmd.Stdout = &stdout
114→	cmd.Stderr = &stderr
115→
116→	err := cmd.Run()
117→	out := Output{
118→		Command: "opencode " + strings.Join(args, " "),
119→		Stdout:  stdout.String(),
120→		Stderr:  stderr.String(),
121→	}
122→
123→	if err != nil {
124→		var exitErr *exec.ExitError
125→		if errors.As(err, &exitErr) {
126→			out.ExitCode = exitErr.ExitCode()
127→		} else {
128→			out.ExitCode = -1
129→		}
130→		return out, err
131→	}
132→
133→	return out, nil
134→}
135→
136→func (a *openCodeAgent) StartSession(ctx context.Context, dir string) (Session, error) {
137→	// opencode's TUI occasionally fails to render on CI (empty pane).
138→	// Retry once if the first attempt produces no output at all.
139→	var s *TmuxSession
140→	var lastErr error
141→	for attempt := range 2 {
142→		name := fmt.Sprintf("opencode-test-%d", time.Now().UnixNano())
143→		var err error
144→		s, err = NewTmuxSession(name, dir, nil, "env", "ENTIRE_TEST_TTY=0", "opencode", "--model", a.model)
145→		if err != nil {
146→			return nil, err
147→		}
148→
149→		// Wait for TUI to be ready (input area with placeholder text).
150→		if _, err := s.WaitFor(`Ask anything`, 15*time.Second); err != nil {
151→			content := s.Capture()
152→			_ = s.Close()
153→			if strings.TrimSpace(content) == "" && attempt == 0 {
154→				lastErr = err
155→				continue
156→			}
157→			return s, fmt.Errorf("waiting for startup: %w", err)
158→		}
159→		s.stableAtSend = ""
160→		return s, nil
161→	}
162→	return nil, fmt.Errorf("opencode TUI failed to start after retry: %w", lastErr)
163→}
