import { useEffect, useRef } from "react";

const DOT_SPACING = 24;
const DOT_RADIUS = 5;
const NOISE_SCALE_X = 0.12;
const NOISE_SCALE_Y = 0.08;
const MAX_DISP_CELLS_X = 3;
const MAX_DISP_CELLS_Y = 1.6;
const CHAOS_START = 0.62;
const CHAOS_END = 0.96;
const DENSITY_FALLOFF_START = 0.8;
const MAX_DROP_RATE = 0.93;
const SCATTER_PEAK = 0.65;
const SCATTER_CURVE = 1.7;
const MORPH_START = 0.28;
const MORPH_END = 0.47;

function smoothstep(edge0: number, edge1: number, x: number) {
  const t = Math.max(0, Math.min(1, (x - edge0) / (edge1 - edge0)));
  return t * t * (3 - 2 * t);
}

function fade(t: number) {
  return t * t * t * (t * (t * 6 - 15) + 10);
}

function lerp(a: number, b: number, t: number) {
  return a + t * (b - a);
}

function hash2(x: number, y: number): number {
  let h = Math.imul(x | 0, 374761393) + Math.imul(y | 0, 668265263);
  h = Math.imul(h ^ (h >>> 13), 1274126177);
  return ((h ^ (h >>> 16)) >>> 0) / 4294967296;
}

function gradDot(ix: number, iy: number, dx: number, dy: number) {
  const angle = hash2(ix, iy) * Math.PI * 2;
  return Math.cos(angle) * dx + Math.sin(angle) * dy;
}

function noise2(x: number, y: number): number {
  const xi = Math.floor(x);
  const yi = Math.floor(y);
  const xf = x - xi;
  const yf = y - yi;
  const u = fade(xf);
  const v = fade(yf);
  const n00 = gradDot(xi, yi, xf, yf);
  const n10 = gradDot(xi + 1, yi, xf - 1, yf);
  const n01 = gradDot(xi, yi + 1, xf, yf - 1);
  const n11 = gradDot(xi + 1, yi + 1, xf - 1, yf - 1);
  return lerp(lerp(n00, n10, u), lerp(n01, n11, u), v);
}

function fbm2(x: number, y: number): number {
  return noise2(x, y) * 0.6 + noise2(x * 2.1, y * 2.1) * 0.3 + noise2(x * 4.3, y * 4.3) * 0.1;
}

function drawDot(ctx: CanvasRenderingContext2D, x: number, y: number, r: number, circleness: number) {
  if (circleness >= 0.995) {
    ctx.beginPath();
    ctx.arc(x, y, r, 0, Math.PI * 2);
    ctx.fill();
    return;
  }
  if (circleness <= 0.005) {
    ctx.fillRect(x - r, y - r, r * 2, r * 2);
    return;
  }
  const cr = r * circleness;
  ctx.beginPath();
  ctx.roundRect(x - r, y - r, r * 2, r * 2, cr);
  ctx.fill();
}

function draw(canvas: HTMLCanvasElement) {
  const ctx = canvas.getContext("2d")!;
  const dpr = window.devicePixelRatio || 1;
  const rect = canvas.getBoundingClientRect();

  canvas.width = rect.width * dpr;
  canvas.height = rect.height * dpr;
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);

  const w = rect.width;
  const h = rect.height;

  const styles = getComputedStyle(canvas);
  const bg = styles.getPropertyValue("--background").trim();
  const fg = styles.getPropertyValue("--foreground").trim();

  ctx.fillStyle = bg;
  ctx.fillRect(0, 0, w, h);

  const cols = Math.floor(w / DOT_SPACING);
  const rows = Math.floor(h / DOT_SPACING);
  const marginX = (w - (cols - 1) * DOT_SPACING) / 2;
  const marginY = (h - (rows - 1) * DOT_SPACING) / 2;
  const maxDispX = DOT_SPACING * MAX_DISP_CELLS_X;
  const maxDispY = DOT_SPACING * MAX_DISP_CELLS_Y;

  ctx.fillStyle = fg;

  for (let row = 0; row < rows; row++) {
    for (let col = 0; col < cols; col++) {
      const t = cols > 1 ? col / (cols - 1) : 0;
      const chaos = smoothstep(CHAOS_START, CHAOS_END, t);
      const circleness = smoothstep(MORPH_START, MORPH_END, t);

      const dropP = smoothstep(DENSITY_FALLOFF_START, 1.0, t) * MAX_DROP_RATE;
      if (hash2(col + 7919, row + 6151) < dropP) continue;

      const nx = fbm2(col * NOISE_SCALE_X, row * NOISE_SCALE_Y);
      const ny = fbm2(col * NOISE_SCALE_X + 137.17, row * NOISE_SCALE_Y + 91.43);

      const jx = hash2(col * 17 + 3, row * 31 + 11) * 2 - 1;
      const jy = hash2(col * 43 + 7, row * 89 + 5) * 2 - 1;

      const scatter = Math.pow(chaos, SCATTER_CURVE) * SCATTER_PEAK;
      const dispX = (nx * (1 - scatter) + jx * scatter) * chaos * maxDispX;
      const dispY = (ny * (1 - scatter) + jy * scatter) * chaos * maxDispY;

      const x = marginX + col * DOT_SPACING + dispX;
      const y = marginY + row * DOT_SPACING + dispY;

      drawDot(ctx, x, y, DOT_RADIUS, circleness);
    }
  }
}

export function FlowField() {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    const canvas = canvasRef.current!;
    draw(canvas);

    const onResize = () => draw(canvas);
    window.addEventListener("resize", onResize);
    return () => window.removeEventListener("resize", onResize);
  }, []);

  return (
    <canvas
      ref={canvasRef}
      style={{ width: "100%", height: "100%", display: "block" }}
    />
  );
}
