import { useEffect, useRef } from "react";

const LINE_COUNT = 42;
const LINE_WIDTH = 1;
const PEAK_X_FRAC = 0.28;
const PEAK_Y_FRAC = 0.32;
const PEAK_AMP_FRAC = 0.22;
const SIGMA_X_FRAC = 0.16;
const SIGMA_Y_FRAC = 0.32;

function gauss2D(
  x: number,
  y: number,
  cx: number,
  cy: number,
  sx: number,
  sy: number,
) {
  const dx = (x - cx) / sx;
  const dy = (y - cy) / sy;
  return Math.exp(-(dx * dx + dy * dy) / 2);
}

function draw(canvas: HTMLCanvasElement) {
  const ctx = canvas.getContext("2d")!;
  const dpr = window.devicePixelRatio || 1;
  const rect = canvas.getBoundingClientRect();

  canvas.width = rect.width * dpr;
  canvas.height = rect.height * dpr;
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);

  const w = rect.width;
  const h = rect.height;

  const styles = getComputedStyle(canvas);
  const bg = styles.getPropertyValue("--background").trim();
  const fg = styles.getPropertyValue("--foreground").trim();

  ctx.fillStyle = bg;
  ctx.fillRect(0, 0, w, h);

  const cx = PEAK_X_FRAC * w;
  const cy = PEAK_Y_FRAC * h;
  const sx = SIGMA_X_FRAC * w;
  const sy = SIGMA_Y_FRAC * h;
  const amp = PEAK_AMP_FRAC * h;

  const spacing = h / (LINE_COUNT + 1);

  ctx.strokeStyle = fg;
  ctx.lineWidth = LINE_WIDTH;
  ctx.lineCap = "butt";

  for (let i = 1; i <= LINE_COUNT; i++) {
    const baseY = spacing * i;
    ctx.beginPath();
    for (let x = 0; x <= w; x += 1) {
      const g = gauss2D(x, baseY, cx, cy, sx, sy);
      const y = baseY + amp * g;
      if (x === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    }
    ctx.stroke();
  }
}

export function FlowField() {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
